changeSet.sql:
SET LOCAL lock_timeout = '5s';
LOCK TABLE nexus.chunks_384, nexus.chunks_768, nexus.chunks_1024 IN ACCESS EXCLUSIVE MODE;
ALTER TABLE nexus.chunks_384  NO FORCE ROW LEVEL SECURITY;
ALTER TABLE nexus.chunks_768  NO FORCE ROW LEVEL SECURITY;
ALTER TABLE nexus.chunks_1024 NO FORCE ROW LEVEL SECURITY;

INSERT INTO nexus.chunks (tenant_id, collection, chash, chunk_text, embedding_384, metadata, created_at)
SELECT tenant_id, collection, chash, chunk_text, embedding, metadata, created_at
FROM nexus.chunks_384;

INSERT INTO nexus.chunks (tenant_id, collection, chash, chunk_text, embedding_768, metadata, created_at)
SELECT tenant_id, collection, chash, chunk_text, embedding, metadata, created_at
FROM nexus.chunks_768;

INSERT INTO nexus.chunks (tenant_id, collection, chash, chunk_text, embedding_1024, metadata, created_at)
SELECT tenant_id, collection, chash, chunk_text, embedding, metadata, created_at
FROM nexus.chunks_1024;

ALTER TABLE nexus.chunks ENABLE ROW LEVEL SECURITY;
ALTER TABLE nexus.chunks FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON nexus.chunks
    USING      (tenant_id = current_setting('nexus.tenant', true))
    WITH CHECK (tenant_id = current_setting('nexus.tenant', true));

CREATE INDEX idx_chunks_embedding_384
    ON nexus.chunks USING hnsw (embedding_384 vector_cosine_ops)
    WITH (m = 16, ef_construction = 64);
CREATE INDEX idx_chunks_embedding_768
    ON nexus.chunks USING hnsw (embedding_768 vector_cosine_ops)
    WITH (m = 16, ef_construction = 64);
CREATE INDEX idx_chunks_embedding_1024
    ON nexus.chunks USING hnsw (embedding_1024 vector_cosine_ops)
    WITH (m = 16, ef_construction = 64);
CREATE INDEX idx_chunks_trgm
    ON nexus.chunks USING GIN (chunk_text gin_trgm_ops);
CREATE INDEX idx_chunks_tsv
    ON nexus.chunks USING GIN (chunk_tsv);
CREATE INDEX idx_chunks_tenant_chash
    ON nexus.chunks (tenant_id, chash);

rollback.sql:
