ALTER TABLE nexus.chunks_384 ADD CONSTRAINT chunks_384_collection_fk FOREIGN KEY (tenant_id, collection) REFERENCES nexus.catalog_collections (tenant_id, name) ON DELETE RESTRICT NOT VALID; ALTER TABLE nexus.chunks_384 VALIDATE CONSTRAINT chunks_384_collection_fk;
